INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZscqGKe3hSa', 4, '{"title":"第20202030条・六元正纪大论篇第七十一","description":"<p>18、凡此太阳司天之政。气化营运先天。天气肃。地气静。寒临太虚。阳气不令。水土合德。上应辰星镇星。其谷玄黅。其政肃。其令徐。寒政大举。泽无阳焰。则火发待时。少阳中治。时雨乃涯。止极雨散。还于太阴。云朝北极。湿化乃布。泽流万物。寒敷于上。雷动于下。寒湿之气。持于气交。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202030,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '18、凡此太阳司天之政。气化营运先天。天气肃。地气静。寒临太虚。阳气不令。水土合德。上应辰星镇星。其谷玄黅。其政肃。其令徐。寒政大举。泽无阳焰。则火发待时。少阳中治。时雨乃涯。止极雨散。还于太阴。云朝北极。湿化乃布。泽流万物。寒敷于上。雷动于下。寒湿之气。持于气交。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
