INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bdJaB45FrSx', 4, '{"title":"第20202036条・六元正纪大论篇第七十一","description":"<p>24、五之气。阳复化。草乃长乃化乃成。民乃舒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202036,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '24、五之气。阳复化。草乃长乃化乃成。民乃舒。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wdeqKuG0Y8t', 4, '{"title":"第20202037条・六元正纪大论篇第七十一","description":"<p>25、终之气。地气正。湿令行。阴凝太虚。埃昏郊野。民乃惨凄。寒风以至。反者孕乃死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202037,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '25、终之气。地气正。湿令行。阴凝太虚。埃昏郊野。民乃惨凄。寒风以至。反者孕乃死。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FTD0Se2b8JA', 4, '{"title":"第20202038条・六元正纪大论篇第七十一","description":"<p>26、故岁宜苦以燥之温之。必折其郁气。先资其化源。抑其运气。扶其不胜。无使暴过而生其疾。食岁谷以全其真。避虚邪以安其正。适气同异。多少制之。同寒湿者燥热化。异寒湿者燥湿化。故同者多之。异者少之。用寒远寒。用凉远凉。用温远温。用热远热。食宜同法。有假者反常。反是者病。所谓时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202038,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '26、故岁宜苦以燥之温之。必折其郁气。先资其化源。抑其运气。扶其不胜。无使暴过而生其疾。食岁谷以全其真。避虚邪以安其正。适气同异。多少制之。同寒湿者燥热化。异寒湿者燥湿化。故同者多之。异者少之。用寒远寒。用凉远凉。用温远温。用热远热。食宜同法。有假者反常。反是者病。所谓时也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
