INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ptt7yvwNWGU', 4, '{"title":"第20202060条・六元正纪大论篇第七十一","description":"<p>48、故食岁谷以安其气。食间谷以去其邪。岁宜以咸以苦以辛。汗之清之散之。安其运气。无使受邪。折其郁气。资其化源。以寒热轻重少多其制。同热者多天化。同清者多地化。用凉远凉。用热远热。用寒远寒。用温远温。食宜同法。有假者反之。此其道也。反是者。乱天地之经。扰阴阳之纪也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202060,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '48、故食岁谷以安其气。食间谷以去其邪。岁宜以咸以苦以辛。汗之清之散之。安其运气。无使受邪。折其郁气。资其化源。以寒热轻重少多其制。同热者多天化。同清者多地化。用凉远凉。用热远热。用寒远寒。用温远温。食宜同法。有假者反之。此其道也。反是者。乱天地之经。扰阴阳之纪也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
