INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YwQcCKGBZfT', 4, '{"title":"第20202078条・六元正纪大论篇第七十一","description":"<p>66、二之气。火反郁。白埃四起。云趋雨府。风不胜湿。雨乃零。民乃康。其病热郁于上。咳逆呕吐。疮发于中。胸嗌不利。头痛身热。昏愦脓疮。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202078,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '66、二之气。火反郁。白埃四起。云趋雨府。风不胜湿。雨乃零。民乃康。其病热郁于上。咳逆呕吐。疮发于中。胸嗌不利。头痛身热。昏愦脓疮。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6m5JC2y9L58', 4, '{"title":"第20202079条・六元正纪大论篇第七十一","description":"<p>67、三之气。天政布。炎暑至。少阳临上。雨乃涯。民病热中。聋瞑血溢。脓疮咳呕。鼽衄渴嚏欠。喉痹目赤。善暴死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202079,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '67、三之气。天政布。炎暑至。少阳临上。雨乃涯。民病热中。聋瞑血溢。脓疮咳呕。鼽衄渴嚏欠。喉痹目赤。善暴死。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s2Fd5OgP0SD', 4, '{"title":"第20202080条・六元正纪大论篇第七十一","description":"<p>68、四之气。凉乃至。炎暑间化。白露降。民气和平。其病满身重。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202080,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '68、四之气。凉乃至。炎暑间化。白露降。民气和平。其病满身重。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('RyT1uN3VT08', 4, '{"title":"第20202081条・六元正纪大论篇第七十一","description":"<p>69、五之气。阳乃去。寒乃来。雨乃降。气门乃闭。刚木早雕。民避寒邪。君子周密。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202081,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '69、五之气。阳乃去。寒乃来。雨乃降。气门乃闭。刚木早雕。民避寒邪。君子周密。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FPcZFLDvJ7Z', 4, '{"title":"第20202082条・六元正纪大论篇第七十一","description":"<p>70、终之气。地气正。风乃至。万物反生。雾以行。其病关闭不禁。心痛。阳气不藏而咳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202082,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '70、终之气。地气正。风乃至。万物反生。雾以行。其病关闭不禁。心痛。阳气不藏而咳。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TB2iXTwtdJa', 4, '{"title":"第20202083条・六元正纪大论篇第七十一","description":"<p>71、抑其运气。赞所不胜。必折其郁气。先取化源。暴过不生。苛疾不起。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202083,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '71、抑其运气。赞所不胜。必折其郁气。先取化源。暴过不生。苛疾不起。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tU8zyhuLF7X', 4, '{"title":"第20202084条・六元正纪大论篇第七十一","description":"<p>72、故岁宜咸辛宜酸。渗之泄之。渍之发之。观气寒温以调其过。同风热者多寒化。异风热者少寒化。用热远热。用温远温。用寒远寒。用凉远凉。食宜同法。此其道也。有假者反之。反是者病之阶也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202084,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '72、故岁宜咸辛宜酸。渗之泄之。渍之发之。观气寒温以调其过。同风热者多寒化。异风热者少寒化。用热远热。用温远温。用寒远寒。用凉远凉。食宜同法。此其道也。有假者反之。反是者病之阶也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
