INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S1IPUX3fsJr', 4, '{"title":"第20202098条・六元正纪大论篇第七十一","description":"<p>86、凡此太阴司天之政。气化营运后天。阴专其政。阳气退辟。大风时起。天气下降。地气上腾。原野昏霿。白埃四起。云奔南极。寒雨数至。物成于差夏。民病寒湿。腹满身䐜愤。胕肿痞逆。寒厥拘急。湿寒合德。黄黑埃昏。流行气交。上应镇星辰星。其政肃、其令寂。其谷玄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202098,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '86、凡此太阴司天之政。气化营运后天。阴专其政。阳气退辟。大风时起。天气下降。地气上腾。原野昏霿。白埃四起。云奔南极。寒雨数至。物成于差夏。民病寒湿。腹满身䐜愤。胕肿痞逆。寒厥拘急。湿寒合德。黄黑埃昏。流行气交。上应镇星辰星。其政肃、其令寂。其谷玄。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HchTkmCHj5F', 4, '{"title":"第20202099条・六元正纪大论篇第七十一","description":"<p>87、故阴凝于上。寒积于下。寒水胜火。则为冰雹。阳光不治。杀气乃行。故有余宜高。不及宜下。有余宜晚。不及宜早。土之利。气之化也。民气亦从之。 间谷命其太也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202099,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '87、故阴凝于上。寒积于下。寒水胜火。则为冰雹。阳光不治。杀气乃行。故有余宜高。不及宜下。有余宜晚。不及宜早。土之利。气之化也。民气亦从之。 间谷命其太也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dLB8Ro9Gzqv', 4, '{"title":"第20202100条・六元正纪大论篇第七十一","description":"<p>88、初之气。地气迁。寒乃去。春气正。风乃来。生布万物以荣。民气条舒。风湿相薄。雨乃后。 民病血溢。筋络拘强。关节不利。身重筋痿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202100,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '88、初之气。地气迁。寒乃去。春气正。风乃来。生布万物以荣。民气条舒。风湿相薄。雨乃后。 民病血溢。筋络拘强。关节不利。身重筋痿。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fpjOFle2tDX', 4, '{"title":"第20202101条・六元正纪大论篇第七十一","description":"<p>89、二之气。大火正、物承化。民乃和。其病温厉大行。远近咸若。湿蒸相薄。雨乃时降。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202101,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '89、二之气。大火正、物承化。民乃和。其病温厉大行。远近咸若。湿蒸相薄。雨乃时降。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1vpJCscqeDQ', 4, '{"title":"第20202102条・六元正纪大论篇第七十一","description":"<p>90、三之气。天政布。湿气降。地气腾。雨乃时降。寒乃随之。感于寒湿。则民病身重胕肿。胸腹满。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202102,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '90、三之气。天政布。湿气降。地气腾。雨乃时降。寒乃随之。感于寒湿。则民病身重胕肿。胸腹满。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bM59T2Aj3jS', 4, '{"title":"第20202103条・六元正纪大论篇第七十一","description":"<p>91、四之气。畏火临。溽蒸化。地气腾。天气痞隔。寒风晓暮。蒸热相薄。草木凝烟。湿化不流。则白露阴布。以成秋令。民病腠理热。血暴溢疟。心腹满热胪胀。甚则胕肿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202103,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '91、四之气。畏火临。溽蒸化。地气腾。天气痞隔。寒风晓暮。蒸热相薄。草木凝烟。湿化不流。则白露阴布。以成秋令。民病腠理热。血暴溢疟。心腹满热胪胀。甚则胕肿。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8Rc9eZHWX6B', 4, '{"title":"第20202104条・六元正纪大论篇第七十一","description":"<p>92、五之气。惨令已行。寒露下。霜乃早降。草木黄落。寒气及体。君子周密。民病皮腠。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202104,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '92、五之气。惨令已行。寒露下。霜乃早降。草木黄落。寒气及体。君子周密。民病皮腠。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sm88tTlJ7BG', 4, '{"title":"第20202105条・六元正纪大论篇第七十一","description":"<p>93、终之气。寒大举。湿大化。霜乃积。阴乃凝。水坚冰。阳光不治。感于寒。则病患关节禁固。腰脽痛。寒湿推于气交而为疾也。必折其郁气。而取化源。益其岁气。无使邪胜。食岁谷以全其真。食间谷以保其精。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202105,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '93、终之气。寒大举。湿大化。霜乃积。阴乃凝。水坚冰。阳光不治。感于寒。则病患关节禁固。腰脽痛。寒湿推于气交而为疾也。必折其郁气。而取化源。益其岁气。无使邪胜。食岁谷以全其真。食间谷以保其精。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('egXtjcUnQaf', 4, '{"title":"第20202106条・六元正纪大论篇第七十一","description":"<p>94、故岁宜以苦燥之温之。甚者发之泄之。不发不泄。则湿气外溢。肉溃皮拆而水血交流。必赞其阳火。令御甚寒。从气异同。少多其判也。同寒者以热化。同湿者以燥化。异者少之。同者多之。用凉远凉。用寒远寒。用温远温。用热远热。食宜同法。假者反之。此其道也。反是者病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202106,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '94、故岁宜以苦燥之温之。甚者发之泄之。不发不泄。则湿气外溢。肉溃皮拆而水血交流。必赞其阳火。令御甚寒。从气异同。少多其判也。同寒者以热化。同湿者以燥化。异者少之。同者多之。用凉远凉。用寒远寒。用温远温。用热远热。食宜同法。假者反之。此其道也。反是者病也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y30P7WbhqXi', 4, '{"title":"第20202107条・六元正纪大论篇第七十一","description":"<p>95、帝曰：善。少阴之政奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202107,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '95、帝曰：善。少阴之政奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
