INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VFp7EzqoS7v', 4, '{"title":"第20202119条・六元正纪大论篇第七十一","description":"<p>107、凡此少阴司天之政。气化营运先天。地气肃。天气明。寒交暑。热加燥。云驰雨府。湿化乃行。时雨乃降。金火合德。上应荧惑太白。其政明。其令切。其谷丹白。水火寒热持于气交而为病始也。热病生于上。清病生于下。寒热凌犯而争于中。民病咳喘。血溢血泄鼽嚏。目赤眦疡。寒厥入胃。心痛腰痛。腹大嗌干肿上。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202119,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '107、凡此少阴司天之政。气化营运先天。地气肃。天气明。寒交暑。热加燥。云驰雨府。湿化乃行。时雨乃降。金火合德。上应荧惑太白。其政明。其令切。其谷丹白。水火寒热持于气交而为病始也。热病生于上。清病生于下。寒热凌犯而争于中。民病咳喘。血溢血泄鼽嚏。目赤眦疡。寒厥入胃。心痛腰痛。腹大嗌干肿上。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
