INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ksvemsMdcJZ', 4, '{"title":"第20202124条・六元正纪大论篇第七十一","description":"<p>112、五之气。畏火临。暑反至。阳乃化。万物乃生乃长荣。民乃康。其病温。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202124,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '112、五之气。畏火临。暑反至。阳乃化。万物乃生乃长荣。民乃康。其病温。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XgwnK8MpHPF', 4, '{"title":"第20202125条・六元正纪大论篇第七十一","description":"<p>113、终之气。燥令行。余火内格。肿于上。咳喘。甚则血溢。寒气数举。则霿雾翳。病生皮腠。内舍于胁。下连少腹而作寒中。地将易也。必抑其运气。资其岁胜。折其郁发。先取化源。无使暴过而生其病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202125,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '113、终之气。燥令行。余火内格。肿于上。咳喘。甚则血溢。寒气数举。则霿雾翳。病生皮腠。内舍于胁。下连少腹而作寒中。地将易也。必抑其运气。资其岁胜。折其郁发。先取化源。无使暴过而生其病也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NhE6fM7fi1G', 4, '{"title":"第20202126条・六元正纪大论篇第七十一","description":"<p>114、食岁谷以全真气。食间谷以辟虚邪。岁宜咸以緛之。而调其上。甚则以苦发之。以酸收之。而安其下。甚则以苦泄之。适气同异而多少之。同天气者以寒清化。同地气者以温热化。用热远热。用凉远凉。用温远温。用寒远寒。食宜同法。有假则反。此其道也。反是者病作矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202126,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '114、食岁谷以全真气。食间谷以辟虚邪。岁宜咸以緛之。而调其上。甚则以苦发之。以酸收之。而安其下。甚则以苦泄之。适气同异而多少之。同天气者以寒清化。同地气者以温热化。用热远热。用凉远凉。用温远温。用寒远寒。食宜同法。有假则反。此其道也。反是者病作矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vYQLUE5PJ5H', 4, '{"title":"第20202127条・六元正纪大论篇第七十一","description":"<p>115、帝曰：善。厥阴之政奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202127,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '115、帝曰：善。厥阴之政奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
