INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('79fqIWiT745', 4, '{"title":"第20202139条・六元正纪大论篇第七十一","description":"<p>127、凡此厥阴司天之政。气化营运后天。诸同正岁。气化营运同天。天气扰。地气正。风生高远。炎热从之。云趋雨府。湿化乃行。风火同德。上应岁星荧惑。其政挠。其令速。其谷苍丹。间谷言太者。其耗文角品羽。 风燥火热。胜复更作。蛰虫来见。流水不冰。热病行于下。风病行于上。风燥胜复形于中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202139,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '127、凡此厥阴司天之政。气化营运后天。诸同正岁。气化营运同天。天气扰。地气正。风生高远。炎热从之。云趋雨府。湿化乃行。风火同德。上应岁星荧惑。其政挠。其令速。其谷苍丹。间谷言太者。其耗文角品羽。 风燥火热。胜复更作。蛰虫来见。流水不冰。热病行于下。风病行于上。风燥胜复形于中。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('c9xfIi54jG5', 4, '{"title":"第20202140条・六元正纪大论篇第七十一","description":"<p>128、初之气。寒始肃。杀气方至。民病寒于右之下。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202140,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '128、初之气。寒始肃。杀气方至。民病寒于右之下。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
