INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SlAK3QZgb2L', 4, '{"title":"第20202142条・六元正纪大论篇第七十一","description":"<p>130、三之气。天政布。风乃时举。民病泣出耳鸣掉眩。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202142,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '130、三之气。天政布。风乃时举。民病泣出耳鸣掉眩。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yaJ3v6K3REz', 4, '{"title":"第20202143条・六元正纪大论篇第七十一","description":"<p>131、四之气。溽暑湿热相薄。争于左之上。民病黄瘅而为胕肿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202143,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '131、四之气。溽暑湿热相薄。争于左之上。民病黄瘅而为胕肿。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
