INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lvn8Lt6Dj6H', 4, '{"title":"第20202145条・六元正纪大论篇第七十一","description":"<p>133、终之气。畏火司令。阳乃大化。蛰虫出见。流水不冰。地气大发。草乃生。人乃舒。其病温厉。必折其郁气。资其化源。赞其运气。无使邪胜。 岁宜以辛调上。以咸调下。畏火之气。无妄犯之。用温远温。用热远热。用凉远凉。用寒远寒。食宜同法。有假反常。此之道也。反是者病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202145,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '133、终之气。畏火司令。阳乃大化。蛰虫出见。流水不冰。地气大发。草乃生。人乃舒。其病温厉。必折其郁气。资其化源。赞其运气。无使邪胜。 岁宜以辛调上。以咸调下。畏火之气。无妄犯之。用温远温。用热远热。用凉远凉。用寒远寒。食宜同法。有假反常。此之道也。反是者病。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V5mzs7kWzC0', 4, '{"title":"第20202146条・六元正纪大论篇第七十一","description":"<p>134、帝曰：善。夫子之言可谓悉矣。然何以明其应乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202146,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '134、帝曰：善。夫子之言可谓悉矣。然何以明其应乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('haU30BHE3ty', 4, '{"title":"第20202147条・六元正纪大论篇第七十一","description":"<p>135、岐伯曰：昭乎哉问也！夫六气者。行有次。止有位。故常以正月朔日平旦视之。睹其位而知其所在矣。运有余。其至先。运不及。其至后。此天之道。气之常也。运非有余非不足。是谓正岁。其至当其时也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202147,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '135、岐伯曰：昭乎哉问也！夫六气者。行有次。止有位。故常以正月朔日平旦视之。睹其位而知其所在矣。运有余。其至先。运不及。其至后。此天之道。气之常也。运非有余非不足。是谓正岁。其至当其时也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('u7ZSUXcI7XL', 4, '{"title":"第20202148条・六元正纪大论篇第七十一","description":"<p>136、帝曰：胜复之气。其常在也。灾眚时至。候也奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202148,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '136、帝曰：胜复之气。其常在也。灾眚时至。候也奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ppmjdpcYyBl', 4, '{"title":"第20202149条・六元正纪大论篇第七十一","description":"<p>137、岐伯曰：非气化者。是谓灾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202149,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '137、岐伯曰：非气化者。是谓灾也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
