INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0fsFewn09bL', 4, '{"title":"第20202151条・六元正纪大论篇第七十一","description":"<p>139、岐伯曰：悉乎哉问也！是明道也。数之始。起于上而终于下。岁半之前。天气主之。岁半之后。地气主之。上下交互。气交主之。岁纪毕矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202151,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '139、岐伯曰：悉乎哉问也！是明道也。数之始。起于上而终于下。岁半之前。天气主之。岁半之后。地气主之。上下交互。气交主之。岁纪毕矣。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
