INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sHFUm2aLqUA', 4, '{"title":"第20202153条・六元正纪大论篇第七十一","description":"<p>141、帝曰：余司其事。则而行之。不合其数何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202153,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '141、帝曰：余司其事。则而行之。不合其数何也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dOmqsmKrZLb', 4, '{"title":"第20202154条・六元正纪大论篇第七十一","description":"<p>142、岐伯曰：气用有多少。化治有盛衰。衰盛多少。同其化也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202154,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '142、岐伯曰：气用有多少。化治有盛衰。衰盛多少。同其化也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('idBpJqh6Nt5', 4, '{"title":"第20202155条・六元正纪大论篇第七十一","description":"<p>143、帝曰：愿闻同化何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202155,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '143、帝曰：愿闻同化何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fgKCR9AsRQL', 4, '{"title":"第20202156条・六元正纪大论篇第七十一","description":"<p>144、岐伯曰：风温春化同。热曛昏火夏化同。胜与复同。燥清烟露秋化同。云雨昏暝埃长夏化同。寒气霜雪冰冬化同。此天地五运六气之化。更用盛衰之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202156,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '144、岐伯曰：风温春化同。热曛昏火夏化同。胜与复同。燥清烟露秋化同。云雨昏暝埃长夏化同。寒气霜雪冰冬化同。此天地五运六气之化。更用盛衰之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gRHc2A8g0Tw', 4, '{"title":"第20202157条・六元正纪大论篇第七十一","description":"<p>145、帝曰： 五营运同天化者。命曰天符。余知之矣。愿闻同地化者何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202157,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '145、帝曰： 五营运同天化者。命曰天符。余知之矣。愿闻同地化者何谓也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('y26pFbbWjFE', 4, '{"title":"第20202158条・六元正纪大论篇第七十一","description":"<p>146、岐伯曰：太过而同天化者三。不及而同天化者 亦三。太过而同地化者三。不及而同地化者亦三。此凡二十四岁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202158,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '146、岐伯曰：太过而同天化者三。不及而同天化者 亦三。太过而同地化者三。不及而同地化者亦三。此凡二十四岁也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wMQJ6WLDRbd', 4, '{"title":"第20202159条・六元正纪大论篇第七十一","description":"<p>147、帝曰：愿闻其所谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202159,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '147、帝曰：愿闻其所谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oDOS8srFMCe', 4, '{"title":"第20202160条・六元正纪大论篇第七十一","description":"<p>148、岐伯曰：甲辰甲戌太宫下加太阴。壬寅壬申太角下加厥阴。庚子庚午太商下加阳明。如是者三。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202160,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '148、岐伯曰：甲辰甲戌太宫下加太阴。壬寅壬申太角下加厥阴。庚子庚午太商下加阳明。如是者三。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9wf8EPEfBse', 4, '{"title":"第20202161条・六元正纪大论篇第七十一","description":"<p>149、癸巳癸亥少征下加少阳。辛丑辛未少羽下加太阳。癸卯癸酉少征下加少阴。如是者三。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202161,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '149、癸巳癸亥少征下加少阳。辛丑辛未少羽下加太阳。癸卯癸酉少征下加少阴。如是者三。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
