INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3cWrp0nSOcU', 4, '{"title":"第20202168条・六元正纪大论篇第七十一","description":"<p>156、帝曰：夫子言用寒远寒。用热远热。余未知其然也。愿闻何谓远？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202168,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '156、帝曰：夫子言用寒远寒。用热远热。余未知其然也。愿闻何谓远？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lbWwX7CjFKV', 4, '{"title":"第20202169条・六元正纪大论篇第七十一","description":"<p>157、岐伯曰：热无犯热。寒无犯寒。从者和。逆者病。不可不敬畏而远之。所谓时兴六位也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202169,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '157、岐伯曰：热无犯热。寒无犯寒。从者和。逆者病。不可不敬畏而远之。所谓时兴六位也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
