INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jHU7Jdmt1Re', 4, '{"title":"第20202246条・六元正纪大论篇第七十一","description":"<p>234、岐伯曰：土郁之发。岩谷震惊。雷殷气交。埃昏黄黑。化为白气。飘骤高深。击石飞空。洪水乃从。川流漫衍。田牧土驹。化气乃敷。善为时雨。始生始长。始化始成。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202246,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '234、岐伯曰：土郁之发。岩谷震惊。雷殷气交。埃昏黄黑。化为白气。飘骤高深。击石飞空。洪水乃从。川流漫衍。田牧土驹。化气乃敷。善为时雨。始生始长。始化始成。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lSfjoZ5MbP4', 4, '{"title":"第20202247条・六元正纪大论篇第七十一","description":"<p>235、故民病心腹胀。肠鸣而为数后。甚则心痛胁䐜。呕吐霍乱。饮发注下。胕肿身重。云奔雨府。霞拥朝阳。山泽埃昏。其乃发也。以其四气。云横天山。浮游生灭。怫之先兆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202247,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '235、故民病心腹胀。肠鸣而为数后。甚则心痛胁䐜。呕吐霍乱。饮发注下。胕肿身重。云奔雨府。霞拥朝阳。山泽埃昏。其乃发也。以其四气。云横天山。浮游生灭。怫之先兆。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qk1X7AHjsjW', 4, '{"title":"第20202248条・六元正纪大论篇第七十一","description":"<p>236、金郁之发。天洁地明。风清气切。大凉乃举。草树浮烟。燥气以行。霿雾数起。杀气来至。草木苍干。金乃有声。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202248,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '236、金郁之发。天洁地明。风清气切。大凉乃举。草树浮烟。燥气以行。霿雾数起。杀气来至。草木苍干。金乃有声。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zg2EFFO9GjW', 4, '{"title":"第20202249条・六元正纪大论篇第七十一","description":"<p>237、故民病咳逆。心胁满引少腹。善暴痛。不可反侧。嗌干面尘色恶。山泽焦枯。土凝霜卤。怫乃发也。其气五。夜零白露。林莽声凄。怫之兆也。  水郁之发。阳气乃辟。阴气暴举。大寒乃至。川泽严凝。寒结为霜雪。甚则黄黑昏翳。流行气交。乃为霜杀。水乃见祥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202249,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '237、故民病咳逆。心胁满引少腹。善暴痛。不可反侧。嗌干面尘色恶。山泽焦枯。土凝霜卤。怫乃发也。其气五。夜零白露。林莽声凄。怫之兆也。 水郁之发。阳气乃辟。阴气暴举。大寒乃至。川泽严凝。寒结为霜雪。甚则黄黑昏翳。流行气交。乃为霜杀。水乃见祥。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sABvzIjCweL', 4, '{"title":"第20202250条・六元正纪大论篇第七十一","description":"<p>238、故民病寒客心痛。腰脽痛。大关节不利。屈伸不便。善厥逆。痞坚腹满。阳光不治。空积沉阴。白埃昏瞑。而乃发也。其气二火前后。太虚深玄。气犹麻散。微见而隐。色黑微黄。怫之先兆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202250,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '238、故民病寒客心痛。腰脽痛。大关节不利。屈伸不便。善厥逆。痞坚腹满。阳光不治。空积沉阴。白埃昏瞑。而乃发也。其气二火前后。太虚深玄。气犹麻散。微见而隐。色黑微黄。怫之先兆也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hhqICeugTHo', 4, '{"title":"第20202251条・六元正纪大论篇第七十一","description":"<p>239、木郁之发。太虚埃昏。云物以扰。大风乃至。屋发折木。木有变。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202251,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '239、木郁之发。太虚埃昏。云物以扰。大风乃至。屋发折木。木有变。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SII3q6a20dj', 4, '{"title":"第20202252条・六元正纪大论篇第七十一","description":"<p>240、故民病胃脘当心而痛。上支两胁。膈咽不通。食饮不下。甚则耳鸣眩转。目不识人。善暴僵仆。太虚苍埃。天山一色。或气浊色。黄黑郁若。横云不起雨。而乃发也。其气无常。 长川草偃。柔叶呈阴。松吟高山。虎啸岩岫。怫之先兆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202252,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '240、故民病胃脘当心而痛。上支两胁。膈咽不通。食饮不下。甚则耳鸣眩转。目不识人。善暴僵仆。太虚苍埃。天山一色。或气浊色。黄黑郁若。横云不起雨。而乃发也。其气无常。 长川草偃。柔叶呈阴。松吟高山。虎啸岩岫。怫之先兆也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1Plm4s9FVg4', 4, '{"title":"第20202253条・六元正纪大论篇第七十一","description":"<p>241、火郁之发。太虚曛翳。大明不彰。炎火行。大暑至。山泽燔燎。材木流津。广厦腾烟。土浮霜卤。止水乃减。蔓草焦黄。风行惑言。湿化乃后。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202253,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '241、火郁之发。太虚曛翳。大明不彰。炎火行。大暑至。山泽燔燎。材木流津。广厦腾烟。土浮霜卤。止水乃减。蔓草焦黄。风行惑言。湿化乃后。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9Hd15GCzff6', 4, '{"title":"第20202254条・六元正纪大论篇第七十一","description":"<p>242、故民病少气。疮疡痈肿。胁腹胸背。面首四肢。䐜愤胪胀。疡痱呕逆。瘛疭骨痛。节乃有动。注下温疟。腹中暴痛。血溢流注。精液乃少。目赤心热。甚则瞀闷懊憹。善暴死。刻终大温。汗濡玄府。其乃发也。其气四。动复则静。阳极反阴。湿令乃化乃成。华发水凝。山川冰雪。焰阳午泽。怫之先兆也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202254,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '242、故民病少气。疮疡痈肿。胁腹胸背。面首四肢。䐜愤胪胀。疡痱呕逆。瘛疭骨痛。节乃有动。注下温疟。腹中暴痛。血溢流注。精液乃少。目赤心热。甚则瞀闷懊憹。善暴死。刻终大温。汗濡玄府。其乃发也。其气四。动复则静。阳极反阴。湿令乃化乃成。华发水凝。山川冰雪。焰阳午泽。怫之先兆也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('h7qFb1tcE6J', 4, '{"title":"第20202255条・六元正纪大论篇第七十一","description":"<p>243、有怫之应而后报也。皆观其极而乃发也。木发无时。水随火也。谨候其时。病可与期。失时反岁。五气不行。生化收藏。政无恒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202255,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '243、有怫之应而后报也。皆观其极而乃发也。木发无时。水随火也。谨候其时。病可与期。失时反岁。五气不行。生化收藏。政无恒也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2ohpHR01V4k', 4, '{"title":"第20202256条・六元正纪大论篇第七十一","description":"<p>244、帝曰：水发而雹雪。土发而飘骤。木发而毁折。金发而。清明。火发而曛昧。何气使然？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202256,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '244、帝曰：水发而雹雪。土发而飘骤。木发而毁折。金发而。清明。火发而曛昧。何气使然？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('JXsr0B2w5fE', 4, '{"title":"第20202257条・六元正纪大论篇第七十一","description":"<p>245、岐伯曰：气有多少。发有微甚。微者当其气。甚者兼其下。征其下气而见可知也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202257,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '245、岐伯曰：气有多少。发有微甚。微者当其气。甚者兼其下。征其下气而见可知也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
