INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kyePBMC6L8u', 4, '{"title":"第20202268条・六元正纪大论篇第七十一","description":"<p>256、帝曰： 四时之气。至有早晏高下左右。其候何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202268,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '256、帝曰： 四时之气。至有早晏高下左右。其候何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mKQ5EVTd05O', 4, '{"title":"第20202269条・六元正纪大论篇第七十一","description":"<p>257、岐伯曰：行有逆顺。至有迟速。故太过者化先天。不及者化后天。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202269,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '257、岐伯曰：行有逆顺。至有迟速。故太过者化先天。不及者化后天。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Oo7Ch7No5N8', 4, '{"title":"第20202270条・六元正纪大论篇第七十一","description":"<p>258、帝曰：愿闻其行何谓也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '258、帝曰：愿闻其行何谓也？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('KtnTfBqjhdm', 4, '{"title":"第20202271条・六元正纪大论篇第七十一","description":"<p>259、岐伯曰：春气西行。夏气北行。秋气东行。冬气南行。故春气始于下。秋气始于上。夏气始于中。冬气始于标。春气始于左。秋气始于右。冬气始于后。夏气始于前。此四时正化之常。故至高之地。冬气常在。至下之地。春气常在。必谨察之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '259、岐伯曰：春气西行。夏气北行。秋气东行。冬气南行。故春气始于下。秋气始于上。夏气始于中。冬气始于标。春气始于左。秋气始于右。冬气始于后。夏气始于前。此四时正化之常。故至高之地。冬气常在。至下之地。春气常在。必谨察之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gw0kTWpZz1I', 4, '{"title":"第20202272条・六元正纪大论篇第七十一","description":"<p>260、帝曰：善。 黄帝问曰：五运六气之应见。六化之正。六变之纪何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202272,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '260、帝曰：善。 黄帝问曰：五运六气之应见。六化之正。六变之纪何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LWBnQpzIapR', 4, '{"title":"第20202273条・六元正纪大论篇第七十一","description":"<p>261、岐伯对曰：夫六气正纪。有化有变。有胜有复。有用有病。不同其候。帝欲何乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202273,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '261、岐伯对曰：夫六气正纪。有化有变。有胜有复。有用有病。不同其候。帝欲何乎？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0XgCIoGm1Cp', 4, '{"title":"第20202274条・六元正纪大论篇第七十一","description":"<p>262、帝曰：愿尽闻之。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202274,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '262、帝曰：愿尽闻之。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gBbmZMuljtn', 4, '{"title":"第20202275条・六元正纪大论篇第七十一","description":"<p>263、岐伯曰：请遂言之。夫气之所至也。厥阴所至为和平。少阴所至为暄。太阴所至为埃溽。少阳所至为炎暑。阳明所至为清劲。太阳所至为寒氛。时化之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202275,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '263、岐伯曰：请遂言之。夫气之所至也。厥阴所至为和平。少阴所至为暄。太阴所至为埃溽。少阳所至为炎暑。阳明所至为清劲。太阳所至为寒氛。时化之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Np2DzsEwD1A', 4, '{"title":"第20202276条・六元正纪大论篇第七十一","description":"<p>264、厥阴所至为风府。为璺启。少阴所至为火府。为舒荣。太阴所至为雨。为员盈。少阳所至为热府。为行出。阳明所至为司杀府。为庚苍。太阳所至为寒府。为归藏。司化之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202276,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '264、厥阴所至为风府。为璺启。少阴所至为火府。为舒荣。太阴所至为雨。为员盈。少阳所至为热府。为行出。阳明所至为司杀府。为庚苍。太阳所至为寒府。为归藏。司化之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('b5B0mrmaFmD', 4, '{"title":"第20202277条・六元正纪大论篇第七十一","description":"<p>265、厥阴所至为生为风摇。少阴所至为荣为形见。太阴所至为化为云雨。少阳所至为长为番鲜。阳明所至为收为雾露。太阳所至为藏为周密。气化之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202277,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '265、厥阴所至为生为风摇。少阴所至为荣为形见。太阴所至为化为云雨。少阳所至为长为番鲜。阳明所至为收为雾露。太阳所至为藏为周密。气化之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('emrR6iT12Cn', 4, '{"title":"第20202278条・六元正纪大论篇第七十一","description":"<p>266、厥阴所至为风生。终为肃。少阴所至为热生。中为寒。太阴所至为湿生。终为注雨。少阳所至为火生。终为蒸溽。阳明所至为燥生。终为凉。太阳所至为寒生。中为温。德化之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202278,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '266、厥阴所至为风生。终为肃。少阴所至为热生。中为寒。太阴所至为湿生。终为注雨。少阳所至为火生。终为蒸溽。阳明所至为燥生。终为凉。太阳所至为寒生。中为温。德化之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FuACpBgnG63', 4, '{"title":"第20202279条・六元正纪大论篇第七十一","description":"<p>267、厥阴所至为毛化。少阴所至为翮化。太阴所至为倮化。少阳所至为羽化。阳明所至为介化。太阳所至为鳞化。德化之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202279,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '267、厥阴所至为毛化。少阴所至为翮化。太阴所至为倮化。少阳所至为羽化。阳明所至为介化。太阳所至为鳞化。德化之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('17mYXZQaB87', 4, '{"title":"第20202280条・六元正纪大论篇第七十一","description":"<p>268、厥阴所至为生化。少阴所至为荣化。太阴所至为濡化。少阳所至为茂化。阳明所至为坚化。太阳所至为藏化。布政之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202280,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '268、厥阴所至为生化。少阴所至为荣化。太阴所至为濡化。少阳所至为茂化。阳明所至为坚化。太阳所至为藏化。布政之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k1rU7gWkRx5', 4, '{"title":"第20202281条・六元正纪大论篇第七十一","description":"<p>269、厥阴所至为飘怒大凉。少阴所至为大暄寒。太阴所至为雷霆骤注烈风。少阳所至为飘风燔燎霜凝。阳明所至为散落温。太阳所至为寒雪冰雹白埃。气变之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202281,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '269、厥阴所至为飘怒大凉。少阴所至为大暄寒。太阴所至为雷霆骤注烈风。少阳所至为飘风燔燎霜凝。阳明所至为散落温。太阳所至为寒雪冰雹白埃。气变之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('gayDlrpwsKK', 4, '{"title":"第20202282条・六元正纪大论篇第七十一","description":"<p>270、厥阴所至为挠动为迎随。少阴所至为高明焰为曛。太阴所至为沉阴为白埃为晦暝。少阳所至为光显为彤云为曛。阳明所至为烟埃为霜为劲切为凄鸣。太阳所至为刚固为坚芒为立。令行之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202282,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '270、厥阴所至为挠动为迎随。少阴所至为高明焰为曛。太阴所至为沉阴为白埃为晦暝。少阳所至为光显为彤云为曛。阳明所至为烟埃为霜为劲切为凄鸣。太阳所至为刚固为坚芒为立。令行之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HCxB9Vjjk1M', 4, '{"title":"第20202283条・六元正纪大论篇第七十一","description":"<p>271、厥阴所至为里急。少阴所至为疡胗身热。太阴所至为积饮痞隔。少阳所至为嚏呕为疮疡。阳明所至为浮虚。太阳所至为屈伸不利。病之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202283,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '271、厥阴所至为里急。少阴所至为疡胗身热。太阴所至为积饮痞隔。少阳所至为嚏呕为疮疡。阳明所至为浮虚。太阳所至为屈伸不利。病之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nRKnvL0S9Y6', 4, '{"title":"第20202284条・六元正纪大论篇第七十一","description":"<p>272、厥阴所至为支痛。少阴所至为惊惑恶寒战谵妄。太阴所至为稸满。少阳所至为惊躁瞀昧暴病。阳明所至为鼽尻阴股膝髀腨䯒足病。太阳所至为腰痛。病之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202284,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '272、厥阴所至为支痛。少阴所至为惊惑恶寒战谵妄。太阴所至为稸满。少阳所至为惊躁瞀昧暴病。阳明所至为鼽尻阴股膝髀腨䯒足病。太阳所至为腰痛。病之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('U73g0ZLtGyj', 4, '{"title":"第20202285条・六元正纪大论篇第七十一","description":"<p>273、厥阴所至为戾。少阴所至为悲妄衄蔑。太阴所至为中满霍乱吐下。少阳所至为喉痹耳鸣呕涌。阳明所至为皴揭。太阳所至为寝汗痉。病之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202285,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '273、厥阴所至为戾。少阴所至为悲妄衄蔑。太阴所至为中满霍乱吐下。少阳所至为喉痹耳鸣呕涌。阳明所至为皴揭。太阳所至为寝汗痉。病之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('crvco0bgj8b', 4, '{"title":"第20202286条・六元正纪大论篇第七十一","description":"<p>274、厥阴所至为胁痛呕泄。少阴所至为语笑。太阴所至为重胕肿。少阳所至为暴注瞤瘛暴死。阳明所至为鼽嚏。太阳所至为流泄禁止。病之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202286,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '274、厥阴所至为胁痛呕泄。少阴所至为语笑。太阴所至为重胕肿。少阳所至为暴注瞤瘛暴死。阳明所至为鼽嚏。太阳所至为流泄禁止。病之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('931VWNaSshG', 4, '{"title":"第20202287条・六元正纪大论篇第七十一","description":"<p>275、凡此十二变者。报德以德。报化以化。报政以政。报令以令。气高则高。气下则下。气后则后。气前则前。气中则中。气外则外。位之常也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202287,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '275、凡此十二变者。报德以德。报化以化。报政以政。报令以令。气高则高。气下则下。气后则后。气前则前。气中则中。气外则外。位之常也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nWQdhl6wGMK', 4, '{"title":"第20202288条・六元正纪大论篇第七十一","description":"<p>276、故风胜则动。热胜则肿。燥胜则干。寒胜则浮。湿胜则濡泄。甚则水闭胕肿。随气所在。以言其变耳。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202288,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '276、故风胜则动。热胜则肿。燥胜则干。寒胜则浮。湿胜则濡泄。甚则水闭胕肿。随气所在。以言其变耳。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H7FRhoHucPz', 4, '{"title":"第20202289条・六元正纪大论篇第七十一","description":"<p>277、帝曰：愿闻其用也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202289,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '277、帝曰：愿闻其用也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nLz6YXmDJNV', 4, '{"title":"第20202290条・六元正纪大论篇第七十一","description":"<p>278、岐伯曰：夫六气之用。各归不胜而为化。故太阴雨化。施于太阳。太阳寒化。施于少阴。少阴热化。施于阳明。阳明燥化。施于厥阴。厥阴风化。施于太阴。各命其所在以征之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202290,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '278、岐伯曰：夫六气之用。各归不胜而为化。故太阴雨化。施于太阳。太阳寒化。施于少阴。少阴热化。施于阳明。阳明燥化。施于厥阴。厥阴风化。施于太阴。各命其所在以征之也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
