INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iCY7CNKdYPe', 4, '{"title":"第20202296条・六元正纪大论篇第七十一","description":"<p>284、岐伯曰：太少异也。太者之至徐而常。少者暴而亡。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202296,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '284、岐伯曰：太少异也。太者之至徐而常。少者暴而亡。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('34aDDYJwcu2', 4, '{"title":"第20202297条・六元正纪大论篇第七十一","description":"<p>285、帝曰：天地之气。盈虚何如？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202297,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '285、帝曰：天地之气。盈虚何如？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dMZ3Q4jbRRC', 4, '{"title":"第20202298条・六元正纪大论篇第七十一","description":"<p>286、岐伯曰：天气不足。地气随之。地气不足。天气从之。运居其中而常先也。恶所不胜。归所同和。随运归从而生其病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202298,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '286、岐伯曰：天气不足。地气随之。地气不足。天气从之。运居其中而常先也。恶所不胜。归所同和。随运归从而生其病也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mXzuHraWVO0', 4, '{"title":"第20202299条・六元正纪大论篇第七十一","description":"<p>287、故上胜则天气降而下。下胜则地气迁而上。多少而差其分。微者小差。甚者大差。甚则位。易气交易。则大变生而病作矣。《大要》曰：甚纪五分。微纪七分。其差可见。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202299,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '287、故上胜则天气降而下。下胜则地气迁而上。多少而差其分。微者小差。甚者大差。甚则位。易气交易。则大变生而病作矣。《大要》曰：甚纪五分。微纪七分。其差可见。此之谓也。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PwoXY6RyZI8', 4, '{"title":"第20202300条・六元正纪大论篇第七十一","description":"<p>288、帝曰：善。论言热无犯热。寒无犯寒。余欲不远寒。不远热奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202300,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '288、帝曰：善。论言热无犯热。寒无犯寒。余欲不远寒。不远热奈何？', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Zae9yV17vX', 4, '{"title":"第20202301条・六元正纪大论篇第七十一","description":"<p>289、岐伯曰：悉乎哉问也！发表不远热。攻里不远寒。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '2024-09-26T13:53:17.000Z', '289、岐伯曰：悉乎哉问也！发表不远热。攻里不远寒。', '2024-09-26T13:53:17.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'I5o7rvhIFfb');
