INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vt4Xd5m3sJt', 4, '{"title":"第20202319条・刺法论篇第七十二","description":"<p>1、黄帝问曰：升降不前。气交有变。即成暴郁。余已知之。如何预救生灵。可得却乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20202319,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '2024-09-26T13:53:18.000Z', '1、黄帝问曰：升降不前。气交有变。即成暴郁。余已知之。如何预救生灵。可得却乎？', '2024-09-26T13:53:18.000Z', 1, NULL, 'drsRImTi5tv', 'section', '3RVxig2C99L');
